export function attachCreditRecovery(plans){
 const plan=plans.find(p=>p.lesson_id==='fe-production-credit-products-04');
 if(!plan)return;
 const segment={id:'example-mentor-recovery',type:'voice.mentor-episode.v2',grading:'none',teaching_role:'example',visual:{type:'speech-plate'},payload:{},copy:{
 'en-US':{prompt:'Rho revises an assumption',setup:'Fictional terms: full timely payment avoids purchase interest; I paid minimum.',misjudgment:'I thought minimum payment stopped interest.',recovery:'I checked: payment was incomplete. These terms still charge interest.'},
 'es-MX':{prompt:'Rho corrige una suposición',setup:'Términos ficticios exigen pago total puntual para evitar intereses de compras; pagué solo mínimo.',misjudgment:'Pensé que pagar mínimo evitaba intereses.',recovery:'Revisé: mi pago fue incompleto. Bajo estos términos, intereses siguen aplicando.'},
 'pt-BR':{prompt:'Rho revê uma suposição',setup:'Termos fictícios exigem pagamento total pontual para evitar juros de compras; paguei só mínimo.',misjudgment:'Pensei que pagar mínimo evitava juros.',recovery:'Conferi: meu pagamento foi incompleto. Sob estes termos, juros ainda se aplicam.'}}};
 plan.segments.splice(2,0,segment);
 plan.mentor_misjudgment={character:'rho',misjudgment:segment.copy['en-US'].misjudgment,recovery:segment.copy['en-US'].recovery};
 plan.instruction.evidence.push({segment_id:segment.id,skill_id:plan.instruction.objective.skill_id,context_id:'production-minimum-payment-mentor-correction',supports_from:[],reasoning:segment.copy['en-US'].recovery});
}
